{
"n": "#158·01",
"text": "This is a floor-length dress made from lightweight black chiffon fabric, featuring an all-over delicate floral print in muted pinks and greens. It has long sleeves with gathered cuffs, a deep V-neckline with optional keyhole detail, and soft ruffles along the hem and waistband for gentle volume."
},
{
"n": "#27·17",
"text": "These are sleek black mules crafted from smooth leather, with a square toe and open back design. The insole is embossed with the brand name, and they sit flat for easy wear throughout the night."
},
{
"n": "#31·13",
"text": "A relaxed-fit black cotton t-shirt with a round crew neck and short sleeves. On the left chest is small white text reading 'КИЇВ ТУТ. ВСЕРЕДИНІ.' in Cyrillic, adding a subtle urban touch."
},
{
"n": "#164·32",
"text": "A simple gold-tone chain-link necklace with medium-sized oval links and a lobster clasp closure. Its minimal design lets it shine subtly against the darker tones of your outfit."
},
{
"n": "#326·03",
"text": "A structured rectangular crossbody bag made of textured orange leather with silver-toned metal hardware on the flap closure and adjustable chain strap. It has a zippered top and a tassel detail hanging from the front."
}
]
